/**
 * As player colors don't change, use this cache to minimize round-tripping to C++ and the compute.
 */
const cachedPlayerColors: Map<number, PlayerColorVariants> = new Map<number, PlayerColorVariants>();

// TODO: Pull from assets/engine so there is an opportunity to get color correct values (HDR, colorblind, etc...)
export enum HighlightColors {
	unitSelection = 0xffdba613,
	unitPossibleMovement = 0xffffff00,
	unitPossibleMovementShadow = 0xffcccc00,
	unitAttack = 0xff001fff,
	unitAttackShadow = 0xff001fdd,
	unitMovementZOC = 0xff0000ff,
	unitMovementZOCShadow = 0x00000000,
	unitCommanderRadius = 0xffffffff,
}

/**
 * The variants of a color
 * @param {string} mainColor The root color
 * @param {string} textColor Body text color (has the most contrast against other colors in the color scheme)
 * @param {string} accentColor Decorative color (has the least contrast against other colors in the color scheme)
 * @param {string} moreColor
 * @param {string} tintColor
 */
export interface ColorVariants {
	mainColor: string;
	textColor: string;
	accentColor: string;
	moreColor: string;
	tintColor: string;
}

/**
 * Variants of the colors used for the player
 * @param {ColorVariants} primaryColor The primary color and its text and accent variants
 * @param {ColorVariants} secondaryColor The secondary color and its text and accent variants
 * @param {boolean} isPrimaryLighter True if the primary color's luminence is lighter than the secondary color
 */
export interface PlayerColorVariants {
	primaryColor: ColorVariants;
	secondaryColor: ColorVariants;
	isPrimaryLighter: boolean;
}

/**
 * Converts an hex number color to a RGB string
 * @param {number} hex
 */
export const numberHexToStringRGB = (hex: number): string => {
	return `rgb(${(hex >> 0) & 0xff},${(hex >> 8) & 0xff},${(hex >> 16) & 0xff})`;
};

/**
 * Applies a player's colors as a CSS variables onto a given element based on the playerId
 *
 * @param element HTMLElement to set css variables on
 * @param playerId ID of the player (determines which colors are used)
 */
export const applyPlayerColorsToElement = (element: HTMLElement, playerId: PlayerId) => {
	// See if values have already been computed.
	let colorVariants: PlayerColorVariants | undefined = cachedPlayerColors.get(playerId);
	if (colorVariants == undefined) {
		const playerColor: PlayerColor | null = UI.Color.getPlayerColors(playerId);
		if (playerColor) {
			colorVariants = UI.Color.createPlayerColorVariants(playerColor);
			cachedPlayerColors.set(playerId, colorVariants); // Store value for subsequent calls.
		} else {
			console.warn(`Unable to get player color for an element using playerID "${playerId}".`);
			return;
		}
	}
	element.style.setProperty("--player-color-primary", colorVariants.primaryColor.mainColor);
	element.style.setProperty("--player-color-primary-more", colorVariants.primaryColor.moreColor);
	element.style.setProperty("--player-color-primary-text", colorVariants.primaryColor.textColor);
	element.style.setProperty("--player-color-primary-accent", colorVariants.primaryColor.accentColor);

	element.style.setProperty("--player-color-secondary", colorVariants.secondaryColor.mainColor);
	element.style.setProperty("--player-color-secondary-more", colorVariants.secondaryColor.moreColor);
	element.style.setProperty("--player-color-secondary-text", colorVariants.secondaryColor.textColor);
	element.style.setProperty("--player-color-secondary-accent", colorVariants.secondaryColor.accentColor);

	element.classList.toggle("primary-color-is-lighter", colorVariants.isPrimaryLighter);
};

const colorVariantsByPlayer = new Map<PlayerId, PlayerColorVariants>();
export const getPlayerColorVariants = (playerId: PlayerId): PlayerColorVariants | undefined => {
	let variants = colorVariantsByPlayer.get(playerId);
	if (!variants) {
		const playerColor = UI.Color.getPlayerColors(playerId);
		if (!playerColor) {
			console.warn(
				`Unable to get player color for playerID "${playerId}". Defaulting to false for isPrimaryColorLighter.`,
			);
			return undefined;
		}
		variants = UI.Color.createPlayerColorVariants(playerColor);
		colorVariantsByPlayer.set(playerId, variants);
	}
	return variants;
};

/**
 * isPrimaryColorLighter outputs a boolean that is true if the primary color is a lighter value than the secondary color
 * @param playerId ID of the player (determines which colors are used)
 */
export const isPrimaryColorLighter = (playerId: PlayerId): boolean => {
	const variants = getPlayerColorVariants(playerId);
	if (!variants) {
		return false;
	}

	return variants.isPrimaryLighter;
};

/**
 * Convert a single hex number RGB (with optional 0.0 to 1.0 alpha) to a float4
 * @param hex RGB packed into a number
 * @param alpha (1.0) an alpha value.
 * @returns Color values broken out into a float4 structure with each value being between 0.0 and 1.0.
 */
export const HexToFloat4 = (hex: number, alpha = 1): float4 => {
	const r = (hex >> 16) & 0xff;
	const g = (hex >> 8) & 0xff;
	const b = hex & 0xff;
	return { x: r / 255, y: g / 255, z: b / 255, w: Math.min(1, Math.max(0, alpha)) };
};

/**
 * Convert R, G, B, and A values into an rgba(r, g, b, a) string
 * @param object Structure with input R, G, B, and A values
 * @returns String in the form "rgba(r, g, b, a)"
 */
export const ObjectToRgbaString = (object: { r: number; g: number; b: number; a: number }): string => {
	return `rgba(${object.r}, ${object.g}, ${object.b}, ${object.a})`;
};

/**
 * Convert RGBA struct into an rgba(r, g, b, a) string
 * @param rgba Structure of type RGBA
 * @returns String in the form "rgba(r, g, b, a)"
 */
export const RGBAToString = (rgba: RGBA): string => {
	return ObjectToRgbaString({ r: rgba.r, g: rgba.g, b: rgba.b, a: rgba.a });
};
